int main() {
    int battery;

    // 1. Read battery percentage from cin
    // 2. If battery >= 25, print SIGMA: ADVANCE
    // 3. Otherwise (else), print SIGMA: RECHARGE

    return 0;
}

steps.solution:
#include <iostream>
using namespace std;

int main() {
    int battery;
    cin >> battery;

    if (battery >= 25) {
        cout << "SIGMA: ADVANCE" << endl;
    } else {
        cout << "SIGMA: RECHARGE" << endl;
    }

    return 0;
}

