    // 3. Else if distance <= 50: ACTION: EVADE OBSTACLE
    // 4. Else: ACTION: CLEAR PATH

    return 0;
}

steps.solution:
#include <iostream>
using namespace std;

int main() {
    int distance;
    cin >> distance;

    if (distance <= 10) {
        cout << "ACTION: EMERGENCY STOP" << endl;
    } else if (distance <= 50) {
        cout << "ACTION: EVADE OBSTACLE" << endl;
    } else {
        cout << "ACTION: CLEAR PATH" << endl;
    }

    return 0;
}
